import {SPOTIFY_LOGIN,restoreSpotifySession,savedSpotifyLinks,spotifyAppLink,addSpotifyLink,removeSpotifyLink} from './spotify-links.mjs';
export function setupSpotifyRadio(storage,onChange){const $=id=>document.getElementById(id);let state=restoreSpotifySession(storage.get('spotify-links',{}));storage.set('spotify-links',savedSpotifyLinks(state));
  const selected=()=>state.stations.find(s=>s.id===state.selectedId);
  function render(){document.querySelectorAll('[data-music-source]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.musicSource==='spotify')===state.external)));$('spotify-panel').classList.toggle('hidden',!state.external);document.querySelector('.radio-tuner').classList.toggle('hidden',state.external);$('music-source-note').textContent=state.external?'Die Spielmusik pausiert. Für Hintergrundmusik die Spotify-App nutzen. Spotify-Wiedergabe und -Lautstärke stellst du dort ein.':'';$('music-volume').disabled=state.external;$('music-mute').disabled=state.external;
    const menu=$('spotify-station');menu.replaceChildren();if(!state.stations.length){const option=document.createElement('option');option.textContent='Noch kein Radio gespeichert';option.value='';menu.append(option);}for(const station of state.stations){const option=document.createElement('option');option.value=station.id;option.textContent=station.label;menu.append(option);}menu.value=state.selectedId;menu.disabled=!state.stations.length;$('spotify-remove').disabled=!state.stations.length;const station=selected();$('spotify-launch').hidden=!station;$('spotify-app-launch').hidden=!station;if(station){$('spotify-app-launch').href=spotifyAppLink(station.url);$('spotify-launch').href=station.url;$('spotify-launch').textContent=station.label+' bei Spotify öffnen ↗';}$('spotify-login').href=SPOTIFY_LOGIN;if(state.external&&window.MetorbikeAndroid)$('music-source-note').textContent='Spotify-App spielt unabhängig weiter. Das Spielaudio pausiert auf Android, damit Spotify nicht unterbrochen wird. Beim Beenden wird die Auswahl im Spiel zurückgesetzt.';
  }
  function save(options){storage.set('spotify-links',savedSpotifyLinks(state));render();onChange(options);}
  document.querySelectorAll('[data-music-source]').forEach(b=>b.addEventListener('click',()=>{state.external=b.dataset.musicSource==='spotify';$('spotify-status').textContent='';save();}));
  $('spotify-add-form').addEventListener('submit',e=>{e.preventDefault();try{state=addSpotifyLink(state,$('spotify-url').value,$('spotify-label').value);save();$('spotify-url').value='';$('spotify-label').value='';$('spotify-status').textContent='Link gespeichert. Öffne den Mix bei Spotify und starte dort die Wiedergabe.';$('spotify-status').dataset.error='false';}catch(error){$('spotify-status').textContent=error.message;$('spotify-status').dataset.error='true';}});
  $('spotify-station').addEventListener('change',e=>{state.selectedId=e.target.value;save();$('spotify-status').textContent='Ausgewählt. Zum Abspielen bei Spotify öffnen.';});
  $('spotify-remove').addEventListener('click',()=>{state=removeSpotifyLink(state,state.selectedId);save();$('spotify-status').textContent='Link entfernt.';});
  $('spotify-launch').addEventListener('click',()=>{$('spotify-status').textContent='Spotify öffnet sich in einem eigenen Tab. Melde dich dort an und starte die Musik. Dieses Spiel kann den Wiedergabestatus nicht sehen.';});
  $('spotify-app-launch').addEventListener('click',e=>{const station=selected();if(!station)return;if(window.MetorbikeAndroid?.openSpotify){e.preventDefault();window.MetorbikeAndroid.openSpotify(station.id);}$('spotify-status').textContent='Starte die Musik in der Spotify-App und kehre anschließend zum Spiel zurück. Die App bleibt für die Wiedergabe zuständig.';});
  function endSession(){state.external=false;save({closing:true});}
  window.addEventListener('pagehide',endSession);window.addEventListener('metorbike:exit',endSession);
  render();return {isExternal:()=>state.external,selectedLabel:()=>selected()?.label||'SPOTIFY EXTERN',endSession};
}
